def populate_languages_en(apps, schema_editor):
    LanguageTranslation = apps.get_model("data", "LanguageTranslation")
    Language = apps.get_model("data", "Language")

    def get_en_title(iso_code, title):
        mapping = {
            "kmr": "Kurmanji",
            "sdh": "Sorani",
            "rom": "Romanes",
            "fa": "Farsi",
        }
        return mapping.get(iso_code, title)

    en, _ = Language.objects.get_or_create(iso_code="en", defaults={"title": "English"})
    languages = Language.objects.all()
    for language_obj in languages:
        try:
            obj = LanguageTranslation(
                language_obj=language_obj,
                language=en,
                title=get_en_title(
                    iso_code=language_obj.iso_code, title=language_obj.title
                ),
            )
            obj.save()
        except Exception:
            continue


